function db(): PDO { static $pdo=null; if ($pdo) return $pdo; $file=getenv('RESTAURANT_DB') ?: rtrim(sys_get_temp_dir(), DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'tokyo-restaurant.sqlite'; if (!is_dir(dirname($file))) mkdir(dirname($file),0770,true); $pdo=new PDO('sqlite:'.$file,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $pdo->exec('PRAGMA foreign_keys=ON'); $pdo->exec('PRAGMA busy_timeout=5000'); $pdo->exec(file_get_contents(__DIR__.'/schema.sql')); $bookingCols=$pdo->query('PRAGMA table_info(bookings)')->fetchAll(PDO::FETCH_COLUMN,1); if(!in_array('zone',$bookingCols,true)) $pdo->exec("ALTER TABLE bookings ADD COLUMN zone TEXT NOT NULL DEFAULT ''"); if(!in_array('preferred_table',$bookingCols,true)) $pdo->exec("ALTER TABLE bookings ADD COLUMN preferred_table TEXT NOT NULL DEFAULT ''); if(!$pdo->query('SELECT 1 FROM app_migrations WHERE version=1')->fetchColumn()) { $pdo->beginTransaction(); try { $pdo->exec(file_get_contents(__DIR__.'/seed.sql')); $pdo->exec('INSERT INTO app_migrations(version) VALUES (1)'); $pdo->commit(); } catch(Throwable $ex) { $pdo->rollBack(); throw $ex; } } return $pdo; }
function e(?string $v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function image_srcset(string $url): string { $parts=parse_url($url); if(!$parts||empty($parts['host'])||!in_array($parts['host'],['images.unsplash.com','plus.unsplash.com'],true)) return ''; parse_str($parts['query']??'', $query); $items=[]; foreach([480,768,1080,1440,2000] as $width){$query['w']=$width;$src=($parts['scheme']??'https').'://'.$parts['host'].($parts['path']??'').'?'.http_build_query($query,'','&',PHP_QUERY_RFC3986);$items[]=$src.' '.$width.'w';} return implode(', ',$items); }
function setting(string $key,string $fallback=''): string { $q=db()->prepare('SELECT value FROM settings WHERE key=?'); $q->execute([$key]); $v=$q->fetchColumn(); return $v===false?$fallback:(string)$v; }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { $v=$_POST['csrf']??($_SERVER['HTTP_X_CSRF_TOKEN']??''); if(!is_string($v)||!hash_equals(csrf(),$v)){http_response_code(419);exit('Сессия формы истекла. Обновите страницу.');} }
function dishes(bool $featured=false): array { $sql='SELECT d.*,c.name category_name FROM dishes d JOIN categories c ON c.slug=d.category WHERE d.active=1'; if($featured)$sql.=' AND d.featured=1'; return db()->query($sql.' ORDER BY d.sort_order,d.id')->fetchAll(); }
